'use strict';

/**
 * A local stand-in for a language model. It is deterministic and works offline: the same input always gives the
 * same output. provider/README.md describes every rule. Use it as it is; do not edit this file.
 */

class ProviderError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ProviderError';
  }
}

const TOKEN = /^sk-local-[A-Za-z0-9]{12,}$/;
const RECORD = '([A-Za-z]+-\\d+)';

const slowMs = () => Number(process.env.STANDIN_SLOW_MS || 1500);
const stepMs = () => Number(process.env.STANDIN_STEP_MS || 500);
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Whether `token` is one this stand-in accepts. */
function check(token) {
  return typeof token === 'string' && TOKEN.test(token);
}

function authorise(token) {
  if (!check(token)) throw new ProviderError('unauthorized: the provider token is missing or wrong');
}

function findRecord(records, id) {
  return (records || []).find((record) => String(record.id).toLowerCase() === id.toLowerCase());
}

function shown(value) {
  return value === undefined || value === null ? 'nothing' : String(value);
}

function typed(current, text) {
  return typeof current === 'number' && /^-?\d+(\.\d+)?$/.test(text) ? Number(text) : text;
}

function proposeSet(records, id, field, text) {
  const record = findRecord(records, id);
  if (!record) return { text: `I can't see a record called ${id.toUpperCase()}.` };
  const to = typed(record[field], text);
  const from = record[field] === undefined ? null : record[field];
  return {
    text: `I propose one change: ${record.id} ${field}: ${shown(from)} → ${shown(to)}. Confirm to apply it.`,
    proposal: { summary: `Set the ${field} of ${record.id} to ${shown(to)}`, changes: [{ record: record.id, field, from, to }] },
  };
}

/**
 * One reply.
 *
 * input:  { token, bot: { name, instructions }, person: { id, name }, memory: [string],
 *           messages: [{ from: 'person' | 'bot', text }], records: [object], attempt: number }
 * output: { text, remember?, forget?, clarify?, proposal?, task?, steer? }
 */
async function respond(input) {
  const { token, bot = {}, memory = [], messages = [], records = [], attempt = 1 } = input || {};
  authorise(token);
  const mine = messages.filter((message) => message.from === 'person');
  const last = messages[messages.length - 1];
  if (!last || last.from !== 'person') throw new ProviderError('the last message must be the person\'s');
  const raw = String(last.text);
  if (raw.includes('[fail once]') && attempt === 1) throw new ProviderError('temporary failure, try again');
  if (raw.includes('[slow]')) await wait(slowMs());
  const said = raw.replace(/\[fail once\]|\[slow\]/g, '').trim();
  let found;

  if ((found = said.match(/^remember that (.+?)\.?$/i))) {
    return { text: `I'll remember that ${found[1]}.`, remember: [found[1]] };
  }
  if ((found = said.match(/^forget (?:that )?(.+?)\.?$/i))) {
    return { text: `I've forgotten "${found[1]}".`, forget: [found[1]] };
  }
  if (/^what do you remember/i.test(said)) {
    return { text: memory.length ? `I remember: ${memory.join('; ')}.` : 'I don\'t remember anything about you yet.' };
  }
  if (/^who are you/i.test(said)) {
    const instructions = String(bot.instructions || '').trim();
    return { text: `I am ${bot.name}.` + (instructions ? ` My instructions: ${instructions}` : ' I have no special instructions.') };
  }
  if (/^what did i ask first/i.test(said)) {
    return { text: mine.length > 1 ? `You first asked: "${mine[0].text}".` : 'This is the first thing you\'ve asked.' };
  }
  if ((found = said.match(/^how many (\w+?)s? can you see/i))) {
    const type = found[1].toLowerCase();
    const count = records.filter((record) => String(record.type).toLowerCase() === type).length;
    return { text: `I can see ${count} ${type} record(s).` };
  }
  if ((found = said.match(new RegExp(`^what is the (\\w+) of ${RECORD}`, 'i')))) {
    const record = findRecord(records, found[2]);
    if (!record) return { text: `I can't see a record called ${found[2].toUpperCase()}.` };
    if (record[found[1]] === undefined) return { text: `${record.id} has no ${found[1]}.` };
    return { text: `The ${found[1]} of ${record.id} is ${shown(record[found[1]])}.` };
  }
  if ((found = said.match(new RegExp(`^set the (\\w+) of ${RECORD} to (.+?)\\.?$`, 'i')))) {
    return proposeSet(records, found[2], found[1], found[3]);
  }
  if ((found = said.match(new RegExp(`^update ${RECORD}\\.?$`, 'i')))) {
    const record = findRecord(records, found[1]);
    if (!record) return { text: `I can't see a record called ${found[1].toUpperCase()}.` };
    return { text: `Which field of ${record.id} should I change, and to what value?`, clarify: true };
  }
  const before = messages[messages.length - 2];
  const asked = before && before.from === 'bot' && String(before.text).match(new RegExp(`^Which field of ${RECORD} should I change`));
  if (asked && (found = said.match(/^(?:the )?(\w+) to (.+?)\.?$/i))) {
    return proposeSet(records, asked[1], found[1], found[2]);
  }
  if ((found = said.match(/^create an order for (.+?) totalling (\d+)\.?$/i))) {
    const order = { type: 'order', customer: found[1], status: 'open', total: Number(found[2]) };
    return {
      text: `I propose creating one order: customer ${order.customer}, total ${order.total}, status open. Confirm to apply it.`,
      proposal: { summary: `Create an order for ${order.customer}`, changes: [{ create: order }] },
    };
  }
  if ((found = said.match(/^(?:long task|research): (.+?)\.?$/i))) {
    const title = found[1];
    const subject = title.replace(/\[[^\]]*\]/g, '').trim();
    const steps = [`Collect what is known about ${subject}`, `Compare the options for ${subject}`, `Write the summary of ${subject}`];
    if (title.includes('[long]')) {
      for (let part = 1; part <= 5; part += 1) steps.splice(steps.length - 1, 0, `Check part ${part} of ${subject}`);
    }
    return { text: `I'll work on "${subject}" in the background and tell you when it is done.`, task: { title: subject, steps, controls: title } };
  }
  if ((found = said.match(/^add step: (.+?)\.?$/i))) {
    return { text: `I'll add "${found[1]}" to the task that is running.`, steer: { add: found[1] } };
  }
  return { text: `You said: "${said}". (${bot.name} has ${mine.length} message(s) from you in this conversation.)` };
}

/**
 * One step of a long task.
 *
 * input:  { token, task: { title, steps, controls }, index: number, attempt: number }
 * output: { text }
 */
async function runStep(input) {
  const { token, task = {}, index = 0, attempt = 1 } = input || {};
  authorise(token);
  await wait(stepMs());
  const steps = task.steps || [];
  if (index < 0 || index >= steps.length) throw new ProviderError(`there is no step ${index + 1}`);
  if (String(task.controls || '').includes('[fail step 2]') && index === 1 && attempt === 1) {
    throw new ProviderError('step 2 failed; it can be tried again');
  }
  return { text: `Done: ${steps[index]}` };
}

module.exports = { ProviderError, check, respond, runStep };
